WITH unpacked AS (SELECT id, latency_ms, status_code, context, SHIFTRIGHT(status_code, 2) AS status_code_high, context['trace'] AS trace, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id FROM app_logs WHERE latency_ms BETWEEN 863 AND 1490) SELECT CASE WHEN latency_ms >= 2586 THEN 'LARGE' ELSE 'SMALL' END AS latency_ms_tier, MIN(status_code_high) AS min_status_code_high, COUNT(*) AS row_count, COUNT(*) AS cnt, APPROX_PERCENTILE(status_code, 0.5) AS status_code_p50, ROUND(AVG(latency_ms), 2) AS avg_latency_ms FROM unpacked GROUP BY CASE WHEN latency_ms >= 2586 THEN 'LARGE' ELSE 'SMALL' END ORDER BY min_status_code_high DESC NULLS FIRST
